import{z as A,x as B,o as l,c as d,q as i,j as n,D as E,d as t,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"尾延迟与对冲请求","description":"","frontmatter":{"title":"尾延迟与对冲请求","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tail-latency-hedging.md","filePath":"cs/tail-latency-hedging.md","lastUpdated":1791063341000}'),p={name:"cs/tail-latency-hedging.md"};function h(c,a,C,m,D,_){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=i('<h1 id="尾延迟与对冲请求" tabindex="-1">尾延迟与对冲请求 <a class="header-anchor" href="#尾延迟与对冲请求" aria-label="Permalink to &quot;尾延迟与对冲请求&quot;">​</a></h1><div class="epigraph"><p>一次用户请求扇出到许多后端，任一慢尾都会变成用户的 P99。对冲是再发一份，用多余负载换尾延迟，必须受预算约束。</p><footer>—— 据 Dean and Barroso, The Tail at Scale, CACM 2013 整理</footer></div><p>上一课<a href="/cs/timeout-backoff">超时退避</a>把重试放在失败之后。缺口是<strong>还没失败、只是慢</strong>：等超时才重试，用户已经付了长尾。Dean–Barroso 提出对冲：短等之后向另一副本再发。本课钉机制与放大风险。后课负载均衡决定第二份打到谁。完整「规模下的尾」在存储运维课序的 Tail at Scale 课还会从机房层再收一次，本课只接通信路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扇出 \\(k\\) 路，独立尾延迟分布的最大值变差。队列、GC、磁盘、包丢都会造长尾。对冲：主请求发出后 \\(t_h\\) 仍无应答，复制一份到另一副本，谁先回用谁，取消另一份（若协议支持）。缺口：对冲在系统已过载时变成雪崩——人人发两份。</p><p>与幂等：对冲写等于并发双执行，必须<a href="/cs/idempotency-keys">幂等键</a>或只对读对冲。</p><p><span class="marginnote">直觉类比：对冲像「外卖十分钟没动静就再下一单，哪家先到吃哪家」。平时多花的只是少量加单费；但饭点系统瘫了、人人都重下单，餐厅就被彻底压垮——所以得限购，这就是全局预算。</span></p><p><span class="marginnote">CACM 2013 把对冲、备用、微分区、tail-tolerant 设计写在同一文。后课 <code>tail-at-scale</code> 从运维与机房再讲，本课不抢那层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>只对幂等读默认对冲。\\(t_h\\) 取历史延迟分位数（如 P95），不要 0（即双发打满）。对冲计入重试预算。取消要真能停下游工作，否则负载仍在。</p><p><span class="marginnote">数字实例：\\(t_h\\) 设在 P95，意味着约 95% 的请求在对冲触发前就已返回——1000 个请求里只有约 50 个多发一份，平均负载只放大 5%；若把 \\(t_h\\) 设成 0（同时双发），负载立刻翻倍。</span></p>',11)),(l(),n(s,null,{default:E(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20A%5B%22%E5%89%AF%E6%9C%AC%20A%22%5D%0A%20%20R%20--%3E%20W%5B%22%E7%AD%89%20t_h%22%5D%0A%20%20W%20--%3E%20B%5B%22%E5%89%AF%E6%9C%AC%20B%20%E5%AF%B9%E5%86%B2%22%5D%0A%20%20A%20--%3E%20WIN%5B%22%E5%85%88%E5%88%B0%E8%80%85%22%5D%0A%20%20B%20--%3E%20WIN%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与熔断：下游已开熔断不要对冲打另一实例同一过载池。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("负载放大：仅当慢尾触发，平均放大远小于 2。过载时人人变慢，\\(t_h\\) 总触发，放大趋近 2，正反馈。所以对冲要有全局预算与「仅健康实例」。这与"),e("a",{href:"/cs/rate-limit-circuit-breaker"},"限流"),t("同一负反馈家族。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者以为「取消了第二份就没代价」。实际上取消只是不再等结果，下游那条慢请求的 CPU 与 IO 往往还在跑——负载没有消失，只是没人等它了，堆积依旧。")],-1)),(l(),n(s,null,{default:E(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OK%5B%22%E7%B3%BB%E7%BB%9F%E5%81%A5%E5%BA%B7%22%5D%20--%3E%20SLOW%5B%22%E4%B8%AA%E5%88%AB%E8%AF%B7%E6%B1%82%E5%8F%98%E6%85%A2%22%5D%0A%20%20SLOW%20--%3E%20HEDGE%5B%22%E8%A7%A6%E5%8F%91%E5%AF%B9%E5%86%B2%EF%BC%9A%E7%AC%AC%E4%BA%8C%E4%BB%BD%22%5D%0A%20%20HEDGE%20--%3E%20W%5B%22%E8%B4%9F%E8%BD%BD%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A%20%20W%20--%3E%20Q%7B%22%E7%B3%BB%E7%BB%9F%E6%98%AF%E5%90%A6%E8%BF%87%E8%BD%BD%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E6%94%BE%E5%A4%A7%E6%9C%89%E9%99%90%22%7C%20OK%0A%20%20Q%20--%3E%7C%22%E6%98%AF%EF%BC%8Ct_h%20%E9%A2%91%E9%A2%91%E8%A7%A6%E5%8F%91%22%7C%20FB%5B%22%E6%AD%A3%E5%8F%8D%E9%A6%88%EF%BC%9A%E6%94%BE%E5%A4%A7%E8%B6%8B%E8%BF%91%E5%8F%8C%E5%80%8D%22%5D%0A%20%20FB%20--%3E%20CUT%5B%22%E9%A2%84%E7%AE%97%E6%88%96%E7%86%94%E6%96%AD%E8%87%AA%E5%8A%A8%E5%85%B3%E5%AF%B9%E5%86%B2%22%5D%0A%20%20CUT%20--%3E%20OK%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>本课不把对冲写成金融对冲。也不写 WAN 任播的全部细节。</p><p>备份请求（hedged）与复制请求（同时双发）差别在 \\(t_h\\)。同时双发延迟更好、平时负载 ×2，只适合极热路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Google 内部的具体 \\(t_h\\) 数字当规范。后课默认：读路径才考虑对冲；写路径先幂等。负载均衡下一课决定副本选择，对冲是第二次选择。Tail at Scale 课把跨层排队再展开。</p><p>慢不等于死。把慢当死而无预算，检测器误伤会变成过载。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扇出放大尾延迟；对冲用第二份换 P99。</li><li>必须延迟触发、计入预算、优先只读。</li><li>过载时对冲变双发，要能自动关掉。</li><li>出处：Dean and Barroso, CACM 2013。</li></ul>',7))])}const F=A(p,[["render",h]]);export{u as __pageData,F as default};
